// -----------------------------------------------------------------------------
// board_pll_model.sv -- TEST-ONLY behavioural stand-in for the two board PLL IP
// modules generated by Gowin.  It matches the REAL vendor port list produced by
// Gowin V1.9.12.04:
//
//   Gowin_PLL_<name>(clkin, init_clk, clkout0, lock);
//
// THIS FILE IS NOT SYNTHESISABLE AND IS NOT PART OF sources.f.  It exists only so
// that sim/test_audio_board.py can exercise the board wrapper (clock_reset.sv /
// top.sv) without the vendor IP.  It does NOT model the physical PFD, VCO, loop
// filter, phase noise, jitter or lock process, and passing the board simulation
// proves NOTHING about the real PLL.
//
// IMPORTANT LIMITATION: a digital simulation cannot synthesise a clock faster
// than its reference from reference edges alone, so this model generates
// clkout0 with a fixed time delay rather than from clkin:
//
//   Gowin_PLL_core_100M     : period 10.000 ns  (100.000 MHz)
//   Gowin_PLL_audio_12M5    : period 80.000 ns  (12.500 MHz; NOT exact 12.288,
//                             functional bring-up -> LRC 48.828 kHz)
//
// lock rises LOCK_EDGES init_clk edges after reset; it is not a physical lock.
// -----------------------------------------------------------------------------
`timescale 1ns/1ps

module Gowin_PLL_core_100M #(
    parameter int  LOCK_EDGES  = 8,
    parameter real CORE_HALF_NS = 5.0
) (
    input  logic clkin,
    input  logic init_clk,
    output logic clkout0,
    output logic lock
);

    logic [7:0] cnt;

    initial begin
        lock    = 1'b0;
        clkout0 = 1'b0;
        cnt     = 8'd0;
    end

    // free-running test clock
    always begin
        #(CORE_HALF_NS);
        clkout0 = ~clkout0;
    end

    always @(posedge init_clk)
        if (cnt < LOCK_EDGES) cnt <= cnt + 8'd1;
        else                  lock <= 1'b1;

endmodule


module Gowin_PLL_audio_12M5 #(
    parameter int  LOCK_EDGES   = 8,
    parameter real AUDIO_HALF_NS = 40.0
) (
    input  logic clkin,
    input  logic init_clk,
    output logic clkout0,
    output logic lock
);

    logic [7:0] cnt;

    initial begin
        lock    = 1'b0;
        clkout0 = 1'b0;
        cnt     = 8'd0;
    end

    always begin
        #(AUDIO_HALF_NS);
        clkout0 = ~clkout0;
    end

    always @(posedge init_clk)
        if (cnt < LOCK_EDGES) cnt <= cnt + 8'd1;
        else                  lock <= 1'b1;

endmodule
